def is_woodall(x):
    if x <= 0:
        return False
    n = 1
    while True:
        woodall = (2 ** n - 1) * n
        if woodall == x:
            return True
        if woodall > x:
            return False
        n += 1

def binary_to_decimal(binary):
    decimal = 0
    for digit in binary:
        decimal = decimal * 2 + int(digit)
