def is_octagonal(n):
    discriminant = 1 + 8 * n
    if discriminant < 0:
        return False
    sqrt_discriminant = int(discriminant ** 0.5)
    if sqrt_discriminant * sqrt_discriminant != discriminant:
        return False
    return (sqrt_discriminant + 1) % 4 == 0

