def max_len_sub(arr, n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    max_len = 1

    for i in range(n):
        for j in range(i + 1, n):
            if abs(arr[j] - arr[i]) == 1:
                pass

    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1 and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
        if dp[i] > max_len:
            max_len = dp[i]

    return max_len
