def is_Monotonic(A):
    if len(A) <= 2:
        return True

    increasing = True
    decreasing = True

    for i in range(1, len(A)):
        if A[i] < A[i-1]:
            increasing = False
        if A[i] > A[i-1]:
            decreasing = False

    return increasing or decreasing

def comb_sort(nums):
    if len(nums) <= 1:
        return nums

    n = len(nums)
    gap = n
    swapped = True

    while gap > 1 or swapped:
        gap = max(1, gap // 1.3)
        swapped = False

        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True

    return nums

