def is_samepatterns(colors, patterns):
    """
    Check whether the colors array follows the sequence given in the patterns array.

    Args:
        colors: List of color values
        patterns: List of pattern values

    Returns:
        bool: True if colors follow the pattern, False otherwise
    """
    if len(colors) != len(patterns):
        return False

    if len(colors) == 0:
        return True

    # Create mappings from pattern to color and color to pattern
    pattern_to_color = {}
    color_to_pattern = {}

    for i in range(len(colors)):
        pattern = patterns[i]
        color = colors[i]

        # Check if pattern already maps to a different color
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

        # Check if color already maps to a different pattern
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

    return True
